  emailSettings=settings||{};const smtpForm=$("#email-settings-form"),messageForm=$("#email-message-settings-form"),canManage=!remoteMode||authState?.is_admin;
  smtpForm.elements.smtp_host.value=settings.smtp_host||"";smtpForm.elements.smtp_port.value=settings.smtp_port||587;smtpForm.elements.security.value=settings.security||"starttls";smtpForm.elements.username.value=settings.username||"";smtpForm.elements.password.value="";smtpForm.elements.password.placeholder=settings.password_configured?"Mot de passe enregistré":"";smtpForm.elements.sender.value=settings.sender||"";
