function dragScrollStep(){dragScrollFrame=0;if(!draggedTreeItem||!dragScrollVelocity)return;const scroller=document.scrollingElement,before=scroller.scrollTop;scroller.scrollTop+=dragScrollVelocity;if(scroller.scrollTop===before){dragScrollVelocity=0;return}dragScrollFrame=requestAnimationFrame(dragScrollStep)}
