const savedTheme=localStorage.getItem(themeKey)||"light";$("#theme-choice").value=savedTheme;applyTheme(savedTheme);$("#theme-choice").onchange=()=>{const choice=$("#theme-choice").value;localStorage.setItem(themeKey,choice);applyTheme(choice);toast("Thème appliqué")};const handleSystemThemeChange=()=>{if((localStorage.getItem(themeKey)||"light")==="auto")applyTheme("auto")};if(systemTheme.addEventListener)systemTheme.addEventListener("change",handleSystemThemeChange);else if(systemTheme.addListener)systemTheme.addListener(handleSystemThemeChange);
function syncColorInputs(){const colors=uiColors();for(const [name,value] of Object.entries(colors)){const input=$(`#color-${name}`);if(input)input.value=value}applyUiColors(colors)}
for(const name of Object.keys(defaultUiColors)){const input=$(`#color-${name}`);if(input)input.oninput=()=>{const colors={...uiColors(),[name]:input.value};localStorage.setItem(colorKey,JSON.stringify(colors));applyUiColors(colors)}}
$("#reset-ui-colors").onclick=()=>{localStorage.removeItem(colorKey);syncColorInputs();toast("Couleurs réinitialisées")};
$("#remote-mutation-cancel").onclick=cancelRemoteMutation;
$("#remote-mutation-retry").onclick=()=>{if(remoteMutation)resumeRemoteMutation(remoteMutation)};
syncColorInputs();
async function saveDefaultLimitWarning(){const warning_seconds=durationFieldsSeconds($("#default-limit-warning").value,$("#default-limit-warning-unit").value);if(!Number.isFinite(warning_seconds)||warning_seconds<1){toast("Indiquez un préavis valide");return}try{await api("/api/v1/actions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"set_default_limit_warning",warning_seconds})});if(state?.settings)state.settings.default_limit_warning_seconds=warning_seconds;toast("Préavis par défaut enregistré")}catch(error){toast(error.message)}}
$("#default-limit-warning").onchange=saveDefaultLimitWarning;
$("#default-limit-warning-unit").onchange=saveDefaultLimitWarning;
$("#login-form").onsubmit=async event=>{event.preventDefault();const formElement=event.currentTarget,form=new FormData(formElement),error=$("#login-error");error.textContent="";setLoginBusy(formElement,true);try{await login(form.get("username"),form.get("password"));formElement.reset()}catch(failure){error.textContent=failure.message}finally{setLoginBusy(formElement,false)}};
$("#first-password-form").onsubmit=async event=>{event.preventDefault();const formElement=event.currentTarget,error=$("#first-password-error");error.textContent="";try{await changePassword(new FormData(formElement));formElement.reset()}catch(failure){error.textContent=failure.message}};
$("#first-email-form").onsubmit=async event=>{event.preventDefault();const formElement=event.currentTarget,error=$("#first-email-error"),form=new FormData(formElement);error.textContent="";try{await saveAccountEmail(form.get("email"),{onboarding:true});formElement.reset()}catch(failure){error.textContent=failure.message}};
async function logout(){try{await api("/api/v1/auth/logout",{method:"POST"})}catch{}authState=null;pendingLogin=null;adminToken=null;localStorage.removeItem(adminTokenKey);$("#header-account").hidden=true;showLogin()}
$("#header-logout").onclick=logout;
function changeSelectedPolicyPerson(value){selectedPolicyUsername=String(value||"");if(selectedPolicyUsername)localStorage.setItem(selectedPolicyUserKey,selectedPolicyUsername);renderPersonChoices();syncPersonDeviceSelection();syncSelectedPersonDevice();renderPersonDeviceScope();selectedPersonalPolicy=null;state=null;analysisHistory=null;todaySessionExplicitlySelected=false;selectedTodaySessionKey="";remoteTodaySessionRows=[];remoteTodaySessionRowsAt=0;remoteTodaySessionRowsScopeKey="";const tab=document.querySelector("[data-tab].active")?.dataset.tab||"today";if(tab==="analysis")showAnalysisPanel("catalog");else if(tab==="activity-details")loadClassification({force:true});else if(tab==="limits")load("scope=limits",{userInitiated:true});else load("scope=today",{userInitiated:true})}
$("#limit-person-choice").onchange=event=>changeSelectedPolicyPerson(event.target.value);
$("#catalog-person-choice").onchange=event=>changeSelectedPolicyPerson(event.target.value);
$("#notification-owner-choice").onchange=event=>{selectedNotificationOwner=String(event.target.value||authState?.username||"");state=null;loadNotifications()};
