$("#install-client-update").onclick=async()=>{if(!confirm("La mise à jour va fermer la PWA locale pendant l’installation. Continuer ?"))return;try{$("#install-client-update").disabled=true;await api("/api/v1/backend/update/install",{method:"POST"});alert("La mise à jour a démarré. La PWA locale va maintenant se fermer ; rouvrez-la depuis l’icône Usage Guard après l’installation.");window.close()}catch(error){toast(error.message)}finally{$("#install-client-update").disabled=false}};
