$("#create-user").onclick=()=>openDialog("Créer un utilisateur",`<label>Identifiant<input name="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,31}" required></label><label>Adresse e-mail (facultative)<input name="email" type="email" autocomplete="email" maxlength="254"></label><label>Mot de passe temporaire<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><label>Confirmer<input name="confirmation" type="password" minlength="10" autocomplete="new-password" required></label><label>Rôle<select name="role">${roleOptions("limited")}</select></label>`,async form=>{const password=form.get("password"),username=String(form.get("username")||""),email=String(form.get("email")||"").trim(),role=String(form.get("role")||"limited"),wantsAdmin=role==="admin";if(password!==form.get("confirmation")){toast("Les mots de passe sont différents");return}try{let created=await api("/api/v1/backend/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username,email,password,role,is_admin:wantsAdmin})});if(wantsAdmin&&!created?.user?.is_admin){created=await api(`/api/v1/backend/users/${encodeURIComponent(username)}/access`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({role:"admin",is_admin:true,permissions:Object.fromEntries(Object.keys(accessLabels).map(key=>[key,true])),email})});if(!created?.user?.is_admin)throw new Error("Le serveur n’a pas confirmé les droits administrateur.")}await loadRemoteUsers();toast(`${roleLabels[role]||"Utilisateur"} créé`)}catch(error){toast(error.message)}});
if(new URLSearchParams(location.search).has("token"))history.replaceState({},"",location.pathname);
const renderOverviewInSelectedLanguage=renderOverview;
renderOverview=function(data,options){if(data?.settings?.language)window.UG_I18N?.setLanguage(data.settings.language);return renderOverviewInSelectedLanguage(data,options)};
if("serviceWorker" in navigator){let reloading=false;navigator.serviceWorker.addEventListener("controllerchange",()=>{if(reloading)return;reloading=true;location.reload()});navigator.serviceWorker.register("service-worker.js?v=1.132",{updateViaCache:"none"}).then(registration=>registration.update())}
checkSession().then(()=>{});setInterval(()=>{if(!appReady)return;if($("#today").classList.contains("active"))load("scope=today",{live:true});else if($("#limits").classList.contains("active"))load("scope=limits",{live:true});else if($("#analysis").classList.contains("active"))refreshAnalysisActivity();else if($("#settings").classList.contains("active")&&!remoteMode&&!$("#backend-traffic-section").hidden)loadBackendTraffic()},centralizedMode()?10000:1000);setInterval(()=>{if(appReady&&!remoteMode)loadClientUpdate()},60000);
